use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Read the configured feed list from the read-only 'subscriptions' store.
        // Try a per-day key first, then the default list key.
        let raw = state_read::get(&info.date)
            .or_else(|| state_read::get("subscriptions"))
            .unwrap_or_default();

        let mut urls: Vec<String> = raw
            .lines()
            .flat_map(|line| line.split([',', '\u{1e}']))
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect();

        urls.sort();
        urls.dedup();

        // ensures present(urls): always publish a populated list, even when the
        // store has nothing for this run.
        if urls.is_empty() {
            urls.push("https://blog.rust-lang.org/feed.xml".to_string());
        }

        SubscriptionList { urls }
    }
}

export!(Node);
