wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Fallback used only when the store holds nothing usable. It must be a host
/// on the downstream fetch allowlist.
const DEFAULT_FEED: &str = "https://simonwillison.net/atom/everything/";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn parse_urls(raw: &str) -> Vec<String> {
    raw.split(|c: char| c == ',' || c == '\u{1e}' || c.is_whitespace())
        .map(|s| s.trim_matches(|c: char| c == '"' || c == '\'' || c == '[' || c == ']'))
        .filter(|s| s.starts_with("http://") || s.starts_with("https://"))
        .map(|s| s.to_string())
        .collect()
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Approved enrichment fetch. RunInfo has no free-text field, so its
        // date is the query. Transport failures come back as values and are
        // ignored; the result never affects the output.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&enrich_url);

        let mut urls: Vec<String> = Vec::new();
        for key in ["subscriptions", "urls", "feeds"] {
            if let Some(raw) = state_read::get(key) {
                urls = parse_urls(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }

        // Keep first-seen order while removing duplicates.
        let mut seen: Vec<String> = Vec::with_capacity(urls.len());
        for u in urls {
            if !seen.contains(&u) {
                seen.push(u);
            }
        }
        let mut urls = seen;

        // ensures present(urls)
        if urls.is_empty() {
            urls.push(DEFAULT_FEED.to_string());
        }

        SubscriptionList { urls }
    }
}

export!(Node);
```

Three things to check about the enrichment fetch:

- **Missing text field:** `RunInfo` has no "text" field, so the enrichment query uses the run's date instead.
- **Host may trap:** if `metadata.internal.example` isn't on this node's HTTP allowlist, the call will trap. The allowlist in the error message doesn't include that host. `fetch` only returns a value for network-level failures (timeouts, error statuses), not for allowlist refusals.
- **Grant mismatch:** the node's `with` clause still grants only `state-read`. The graph declaration needs updating to match the approved `http-client` grant.

